import{_ as l,a0 as d,w as o,s as c,ao as t,I as i,x as n,a1 as p,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"深入學習 Linux 內核模組 | LCTT x X-CMD","titleTemplate":false,"description":"深入學習 Linux 內核模組 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"深入學習 Linux 內核模組 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"深入學習 Linux 內核模組 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190501 Looking into Linux modules","title":"深入學習 Linux 內核模組","tag":"201907","desc":""},"relativePath":"201907/20190501 Looking into Linux modules.md","filePath":"[post].md"}'),r={name:"201907/20190501 Looking into Linux modules.md"};function _(h,s,m,k,u,g){const a=d("Link");return o(),c("div",null,[s[15]||(s[15]=t(`<h1 id="深入學習-linux-內核模組" tabindex="-1">深入學習 Linux 內核模組 <a class="header-anchor" href="#深入學習-linux-內核模組" aria-label="Permalink to “深入學習 Linux 內核模組”">​</a></h1><blockquote><p>lsmod 命令能夠告訴你當前系統上加載了哪些內核模組，以及關於使用它們的一些有趣的細節。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/04/modules-100794941-large.jpg" alt="Rob Oo CC BY 2.0"></p><h3 id="什麼是-linux-內核模組" tabindex="-1">什麼是 Linux 內核模組？ <a class="header-anchor" href="#什麼是-linux-內核模組" aria-label="Permalink to “什麼是 Linux 內核模組？”">​</a></h3><p>內核模組是可以根據需要加載到內核中或從內核中卸載的代碼塊，因此無需重啓就可以擴展內核的功能。事實上，除非用户使用類似 <code>lsmod</code> 這樣的命令來查詢模組信息，否則用户不太可能知道內核發生的任何變化。</p><p>需要知道的重要一點是，在你的 Linux 系統上總會有<em>很多</em>可用的模組，並且如果你可以深入其中瞭解到很多細節。</p><p><code>lsmod</code> 的主要用途之一是在系統不能正常工作時檢查模組。然而，大多數情況下，模組會根據需要加載的，而且用户不需要知道它們如何運作。</p><h3 id="顯示內核模組" tabindex="-1">顯示內核模組 <a class="header-anchor" href="#顯示內核模組" aria-label="Permalink to “顯示內核模組”">​</a></h3><p>顯示內核模組最簡單的方法是使用 <code>lsmod</code> 命令。雖然這個命令包含了很多細節，但輸出卻是非常用户友好。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsmod</span></span>
<span class="line"><span>Module                  Size  Used by</span></span>
<span class="line"><span>snd_hda_codec_realtek 114688  1</span></span>
<span class="line"><span>snd_hda_codec_generic  77824  1 snd_hda_codec_realtek</span></span>
<span class="line"><span>ledtrig_audio          16384  2 snd_hda_codec_generic,snd_hda_codec_realtek</span></span>
<span class="line"><span>snd_hda_codec_hdmi     53248  1</span></span>
<span class="line"><span>snd_hda_intel          40960  2</span></span>
<span class="line"><span>snd_hda_codec         131072  4 snd_hda_codec_generic,snd_hda_codec_hdmi,snd_hda_intel</span></span>
<span class="line"><span>                                ,snd_hda_codec_realtek</span></span>
<span class="line"><span>snd_hda_core           86016  5 snd_hda_codec_generic,snd_hda_codec_hdmi,snd_hda_intel</span></span>
<span class="line"><span>                                ,snd_hda_codec,snd_hda_codec_realtek</span></span>
<span class="line"><span>snd_hwdep              20480  1 snd_hda_codec</span></span>
<span class="line"><span>snd_pcm               102400  4 snd_hda_codec_hdmi,snd_hda_intel,snd_hda_codec,snd_hda</span></span>
<span class="line"><span>                                _core</span></span>
<span class="line"><span>snd_seq_midi           20480  0</span></span>
<span class="line"><span>snd_seq_midi_event     16384  1 snd_seq_midi</span></span>
<span class="line"><span>dcdbas                 20480  0</span></span>
<span class="line"><span>snd_rawmidi            36864  1 snd_seq_midi</span></span>
<span class="line"><span>snd_seq                69632  2 snd_seq_midi,snd_seq_midi_event</span></span>
<span class="line"><span>coretemp               20480  0</span></span>
<span class="line"><span>snd_seq_device         16384  3 snd_seq,snd_seq_midi,snd_rawmidi</span></span>
<span class="line"><span>snd_timer              36864  2 snd_seq,snd_pcm</span></span>
<span class="line"><span>kvm_intel             241664  0</span></span>
<span class="line"><span>kvm                   626688  1 kvm_intel</span></span>
<span class="line"><span>radeon               1454080  10</span></span>
<span class="line"><span>irqbypass              16384  1 kvm</span></span>
<span class="line"><span>joydev                 24576  0</span></span>
<span class="line"><span>input_leds             16384  0</span></span>
<span class="line"><span>ttm                   102400  1 radeon</span></span>
<span class="line"><span>drm_kms_helper        180224  1 radeon</span></span>
<span class="line"><span>drm                   475136  13 drm_kms_helper,radeon,ttm</span></span>
<span class="line"><span>snd                    81920  15 snd_hda_codec_generic,snd_seq,snd_seq_device,snd_hda</span></span>
<span class="line"><span>                                 _codec_hdmi,snd_hwdep,snd_hda_intel,snd_hda_codec,snd</span></span>
<span class="line"><span>                                 _hda_codec_realtek,snd_timer,snd_pcm,snd_rawmidi</span></span>
<span class="line"><span>i2c_algo_bit           16384  1 radeon</span></span>
<span class="line"><span>fb_sys_fops            16384  1 drm_kms_helper</span></span>
<span class="line"><span>syscopyarea            16384  1 drm_kms_helper</span></span>
<span class="line"><span>serio_raw              20480  0</span></span>
<span class="line"><span>sysfillrect            16384  1 drm_kms_helper</span></span>
<span class="line"><span>sysimgblt              16384  1 drm_kms_helper</span></span>
<span class="line"><span>soundcore              16384  1 snd</span></span>
<span class="line"><span>mac_hid                16384  0</span></span>
<span class="line"><span>sch_fq_codel           20480  2</span></span>
<span class="line"><span>parport_pc             40960  0</span></span>
<span class="line"><span>ppdev                  24576  0</span></span>
<span class="line"><span>lp                     20480  0</span></span>
<span class="line"><span>parport                53248  3 parport_pc,lp,ppdev</span></span>
<span class="line"><span>ip_tables              28672  0</span></span>
<span class="line"><span>x_tables               40960  1 ip_tables</span></span>
<span class="line"><span>autofs4                45056  2</span></span>
<span class="line"><span>raid10                 57344  0</span></span>
<span class="line"><span>raid456               155648  0</span></span>
<span class="line"><span>async_raid6_recov      24576  1 raid456</span></span>
<span class="line"><span>async_memcpy           20480  2 raid456,async_raid6_recov</span></span>
<span class="line"><span>async_pq               24576  2 raid456,async_raid6_recov</span></span>
<span class="line"><span>async_xor              20480  3 async_pq,raid456,async_raid6_recov</span></span>
<span class="line"><span>async_tx               20480  5 async_pq,async_memcpy,async_xor,raid456,async_raid6_re</span></span>
<span class="line"><span>                                cov</span></span>
<span class="line"><span>xor                    24576  1 async_xor</span></span>
<span class="line"><span>raid6_pq              114688  3 async_pq,raid456,async_raid6_recov</span></span>
<span class="line"><span>libcrc32c              16384  1 raid456</span></span>
<span class="line"><span>raid1                  45056  0</span></span>
<span class="line"><span>raid0                  24576  0</span></span>
<span class="line"><span>multipath              20480  0</span></span>
<span class="line"><span>linear                 20480  0</span></span>
<span class="line"><span>hid_generic            16384  0</span></span>
<span class="line"><span>psmouse               151552  0</span></span>
<span class="line"><span>i2c_i801               32768  0</span></span>
<span class="line"><span>pata_acpi              16384  0</span></span>
<span class="line"><span>lpc_ich                24576  0</span></span>
<span class="line"><span>usbhid                 53248  0</span></span>
<span class="line"><span>hid                   126976  2 usbhid,hid_generic</span></span>
<span class="line"><span>e1000e                245760  0</span></span>
<span class="line"><span>floppy                 81920  0</span></span></code></pre></div><p>在上面的輸出中：</p><ul><li><code>Module</code> 顯示每個模組的名稱</li><li><code>Size</code> 顯示每個模組的大小（並不是它們佔的內存大小）</li><li><code>Used by</code> 顯示每個模組被使用的次數和使用它們的模組</li></ul><p>顯然，這裏有<em>很多</em>模組。加載的模組數量取決於你的系統和版本以及正在運行的內容。我們可以這樣計數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsmod | wc -l</span></span>
<span class="line"><span>67</span></span></code></pre></div><p>要查看系統中可用的模組數（不止運行當中的），試試這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ modprobe -c | wc -l</span></span>
<span class="line"><span>41272</span></span></code></pre></div><h3 id="與內核模組相關的其他命令" tabindex="-1">與內核模組相關的其他命令 <a class="header-anchor" href="#與內核模組相關的其他命令" aria-label="Permalink to “與內核模組相關的其他命令”">​</a></h3><p>Linux 提供了幾條用於羅列、加載及卸載、測試，以及檢查模組狀態的命令。</p><ul><li><code>depmod</code> —— 生成 <code>modules.dep</code> 和映射文件</li><li><code>insmod</code> —— 一個往 Linux 內核插入模組的程序</li><li><code>lsmod</code> —— 顯示 Linux 內核中模組狀態</li><li><code>modinfo</code> —— 顯示 Linux 內核模組信息</li><li><code>modprobe</code> —— 添加或移除 Linux 內核模組</li><li><code>rmmod</code> —— 一個從 Linux 內核移除模組的程序</li></ul><h3 id="顯示內置的內核模組" tabindex="-1">顯示內置的內核模組 <a class="header-anchor" href="#顯示內置的內核模組" aria-label="Permalink to “顯示內置的內核模組”">​</a></h3><p>正如前文所説，<code>lsmod</code> 命令是顯示內核模組最方便的命令。然而，也有其他方式可以顯示它們。<code>modules.builtin</code> 文件中列出了所有構建在內核中的模組，在 <code>modprobe</code> 命令嘗試添加文件中的模組時會使用它。注意，以下命令中的 <code>$(uname -r)</code> 提供了內核版本的名稱。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ more /lib/modules/$(uname -r)/modules.builtin | head -10</span></span>
<span class="line"><span>kernel/arch/x86/crypto/crc32c-intel.ko</span></span>
<span class="line"><span>kernel/arch/x86/events/intel/intel-uncore.ko</span></span>
<span class="line"><span>kernel/arch/x86/platform/intel/iosf_mbi.ko</span></span>
<span class="line"><span>kernel/mm/zpool.ko</span></span>
<span class="line"><span>kernel/mm/zbud.ko</span></span>
<span class="line"><span>kernel/mm/zsmalloc.ko</span></span>
<span class="line"><span>kernel/fs/binfmt_script.ko</span></span>
<span class="line"><span>kernel/fs/mbcache.ko</span></span>
<span class="line"><span>kernel/fs/configfs/configfs.ko</span></span>
<span class="line"><span>kernel/fs/crypto/fscrypto.ko</span></span></code></pre></div><p>你可以使用 <code>modinfo</code> 獲得一個模組的更多細節，雖然沒有對模組提供的服務的簡單説明。下面輸出內容中省略了冗長的簽名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ modinfo floppy | head -16</span></span>
<span class="line"><span>filename:       /lib/modules/5.0.0-13-generic/kernel/drivers/block/floppy.ko</span></span>
<span class="line"><span>alias:          block-major-2-*</span></span>
<span class="line"><span>license:        GPL</span></span>
<span class="line"><span>author:         Alain L. Knaff</span></span>
<span class="line"><span>srcversion:     EBEAA26742DF61790588FD9</span></span>
<span class="line"><span>alias:          acpi*:PNP0700:*</span></span>
<span class="line"><span>alias:          pnp:dPNP0700*</span></span>
<span class="line"><span>depends:</span></span>
<span class="line"><span>retpoline:      Y</span></span>
<span class="line"><span>intree:         Y</span></span>
<span class="line"><span>name:           floppy</span></span>
<span class="line"><span>vermagic:       5.0.0-13-generic SMP mod_unload</span></span>
<span class="line"><span>sig_id:         PKCS#7</span></span>
<span class="line"><span>signer:</span></span>
<span class="line"><span>sig_key:</span></span>
<span class="line"><span>sig_hashalgo:   md4</span></span></code></pre></div><p>你可以使用 <code>modprobe</code> 命令加載或卸載模組。使用下面這條命令，你可以找到特定模組關聯的內核對象：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find /lib/modules/$(uname -r) -name floppy*</span></span>
<span class="line"><span>/lib/modules/5.0.0-13-generic/kernel/drivers/block/floppy.ko</span></span></code></pre></div><p>如果你想要加載模組，你可以使用這個命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo modprobe floppy</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>很明顯，內核模組的加載和卸載非常重要。它使得 Linux 系統比使用通用內核運行時更加靈活和高效。這同樣意味着你可以進行重大更改而無需重啓，例如添加硬件。</p><hr>`,31)),i("p",null,[s[1]||(s[1]=n("via: ",-1)),p(a,{href:"https://www.networkworld.com/article/3391362/looking-into-linux-modules.html"},{default:e(()=>[...s[0]||(s[0]=[n("https://www.networkworld.com/article/3391362/looking-into-linux-modules.html",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=n("作者：",-1)),p(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:e(()=>[...s[2]||(s[2]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=n(" 選題：",-1)),p(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 譯者：",-1)),p(a,{href:"https://github.com/LazyWolfLin"},{default:e(()=>[...s[4]||(s[4]=[n("LazyWolfLin",-1)])]),_:1}),s[9]||(s[9]=n(" 校對：",-1)),p(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=n("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原創編譯，",-1)),p(a,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[n("Linux中國",-1)])]),_:1}),s[14]||(s[14]=n(" 榮譽推出",-1))])])}const x=l(r,[["render",_]]);export{y as __pageData,x as default};
